private.retention_retire_source:
CREATE OR REPLACE FUNCTION private.retention_retire_source(p_source uuid, p_reason text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.historical_report_runs;b public.analysis_jev_batch_runs;sc public.report_corpus_scopes;r public.analysis_parallel_reports;t text;prior text;begin

 select * into s from public.historical_report_runs where id=p_source;
 if s.id is null then return true;end if; perform pg_advisory_xact_lock(hashtextextended('recent-text-corpus:'||s.establishment_id::text,0)); select * into s from public.historical_report_runs where id=p_source for update; if s.id is null then return true;end if;
 select * into b from public.analysis_jev_batch_runs where current_source_run_id=p_source;
 if b.id is not null and (exists(select 1 from public.analysis_jev_batch_tasks where run_id=b.id and status='reserved' and lease_until>now()) or b.sol_request_count=1 and b.sol_receipt is null and b.sol_lease_until>now()) then
  update public.analysis_jev_batch_runs set armed=false where id=b.id;
  update public.report_corpus_scopes set stale=true,stale_reason=p_reason where source_run_id=p_source;
  return false;
 end if;
 select * into sc from public.report_corpus_scopes where source_run_id=p_source;
 select * into r from public.analysis_parallel_reports where current_source_run_id=p_source;
 if sc.source_run_id is not null then insert into private.retired_report_scopes(establishment_id,language,organization_id,report_id,source_run_id,generated_at,review_count,period_start,period_end,reason)
  values(s.establishment_id,s.language,s.organization_id,r.id,s.id,r.generated_at,sc.review_count,sc.period_start,sc.period_end,p_reason)
  on conflict(establishment_id,language) do update set report_id=excluded.report_id,source_run_id=excluded.source_run_id,generated_at=excluded.generated_at,review_count=excluded.review_count,period_start=excluded.period_start,period_end=excluded.period_end,retired_at=now(),reason=excluded.reason;end if;
 perform private.record_retention_attempt('public.analysis_jev_batch_runs',to_jsonb(b));
 perform private.record_retention_attempt('public.analysis_jev_batch_tasks',to_jsonb(x)) from public.analysis_jev_batch_tasks x where run_id=b.id;
 insert into private.retired_generation_keys select id,source_run_id,now(),(select epoch from public.review_corpus_policy) from public.report_generation_requests where source_run_id=p_source on conflict do nothing;
 prior=current_setting('home.retention_maintenance',true);perform set_config('home.retention_maintenance','on',true);
 -- Explicit reviewed current-pipeline tables only. FK constraints remain on.

 delete from public.report_corpus_scopes where source_run_id=p_source;
 delete from public.report_generation_abandonments where source_run_id=p_source;
 delete from public.report_generation_requests where source_run_id=p_source;
 delete from public.analysis_jev_batch_tasks where run_id=b.id;
 delete from public.analysis_jev_batch_runs where id=b.id;
 delete from public.analysis_parallel_reports where current_source_run_id=p_source;
 delete from public.analysis_parallel_launch_preparations where current_source_run_id=p_source;
 delete from public.historical_report_runs where id=p_source;

 perform set_config('home.retention_maintenance',coalesce(prior,''),true);return true;
end $function$

private.store_current_report_publication:
CREATE OR REPLACE FUNCTION private.store_current_report_publication(p jsonb, sc jsonb, p_created_at timestamp with time zone, p_recovery boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare doc jsonb;bindings jsonb;ev jsonb;meta jsonb;is_stale boolean;s record;changed integer;
begin
 if p->>'state' is distinct from 'completed' or p#>>'{controls,technical_checks_passed}' is distinct from 'true'
 or p#>'{derived_report,report}' is null or p->>'generated_at' is null or sc->>'source_run_id' is distinct from p->>'current_source_run_id'
 or sc->>'establishment_id' is distinct from p->>'establishment_id' or sc->>'organization_id' is distinct from p->>'organization_id'
 or p_created_at is null then raise exception 'PUBLICATION_SOURCE_INVALID';end if;
 perform pg_advisory_xact_lock(hashtextextended('recent-text-corpus:'||(p->>'establishment_id'),0));
 is_stale=coalesce((sc->>'stale')::boolean,false) or sc->>'fingerprint' is distinct from public.review_corpus_fingerprint((p->>'establishment_id')::uuid);
 is_stale=is_stale or not exists(select 1 from public.review_corpus_policy where enabled and not paused and epoch::text=sc->>'policy_epoch'); if not p_recovery and not exists(select 1 from public.historical_report_runs where id=(p->>'current_source_run_id')::uuid and establishment_id=(p->>'establishment_id')::uuid and organization_id=(p->>'organization_id')::uuid and language=p->>'language') then raise exception 'PUBLICATION_TENANT_OR_LANGUAGE_CHANGED';end if; if is_stale and not p_recovery then return false;end if;
 select coalesce(jsonb_agg(x),'[]') into bindings from (
  select jsonb_build_object('id',r->>'id','rating',r->'rating','published_at',r->'published_at','analysis_language',r->'analysis_language',
   'original_language',coalesce(r->'original_language',r#>'{translation_provenance,original_language}'),'analysis_source',r->'analysis_source','translation_provenance',r->'translation_provenance','review_detailed_rating',r->'review_detailed_rating','review_context',private.recommendation_spend_context_v1(r->'review_context'),
   'analysis_text_sha256',coalesce(r->>'analysis_text_sha256',encode(extensions.digest(coalesce(r->>'analysis_text',''),'sha256'),'hex')),
   'original_text_sha256',coalesce(r->>'original_text_sha256',encode(extensions.digest(coalesce(r->>'original_text',''),'sha256'),'hex'))) x
  from jsonb_array_elements(p->'source_reviews') r) t;
 if jsonb_array_length(bindings)<>(sc->>'review_count')::int then raise exception 'PUBLICATION_BINDINGS_INCOMPLETE';end if;
 select coalesce(jsonb_agg(jsonb_build_object('evidence_id',e->>'evidence_id','review_id',e->>'review_id','category',e->>'category','polarity',e->>'polarity','quote_sha256',e->>'quote_sha256')),'[]') into ev from jsonb_array_elements(p#>'{controls,evidence}') e;
 select coalesce(jsonb_object_agg(k,v),'{}') into meta from jsonb_each(case when jsonb_typeof(p->'source_report')='object' then p->'source_report' else '{}'::jsonb end) x(k,v)
 where k in('generation_id','ai_status','stored_reviews_count','preferred_language','sample_average_rating','food_average','food_review_count','service_average','service_review_count','atmosphere_average','atmosphere_review_count','customer_rating_statistics','analysis_input_stats');
 doc=jsonb_build_object('id',p->'id','current_source_run_id',p->'current_source_run_id','reference_generation_id',p->'reference_generation_id','state','completed','error_code',null,
  'created_at',p->'created_at','generated_at',p->'generated_at','configuration_version',p->'configuration_version','derived_report',private.publication_generated_report(p->'derived_report'),
  'original_report',null,'raw_response',null,'corrections',null,'source_report',meta,'source_reviews','[]'::jsonb,'statistics',p->'statistics','usage',p->'usage',
  'controls',jsonb_build_object('technical_checks_passed',true,'section_issues','[]'::jsonb,'semantic_correctness_guaranteed',false,'dated_publication',true));
 insert into public.current_report_publications(establishment_id,organization_id,language,report_id,source_run_id,source_created_at,generated_at,scope,document,source_bindings,evidence_bindings,stale,stale_reason,provenance)
 values((p->>'establishment_id')::uuid,(p->>'organization_id')::uuid,p->>'language',(p->>'id')::uuid,(p->>'current_source_run_id')::uuid,p_created_at,(p->>'generated_at')::timestamptz,sc,doc,bindings,ev,is_stale,case when is_stale then 'CORPUS_CHANGED' end,
  jsonb_build_object('method',case when p_recovery then 'saved_response_dated_recovery' else 'validated_current_publication' end,'provider_calls',0))
 on conflict(establishment_id,language) do update set report_id=excluded.report_id,source_run_id=excluded.source_run_id,source_created_at=excluded.source_created_at,
  generated_at=excluded.generated_at,scope=excluded.scope,document=excluded.document,source_bindings=excluded.source_bindings,evidence_bindings=excluded.evidence_bindings,
  stale=excluded.stale,stale_reason=excluded.stale_reason,provenance=excluded.provenance,updated_at=now()
 where current_report_publications.report_id<>excluded.report_id and (excluded.source_created_at,excluded.source_run_id)>(current_report_publications.source_created_at,current_report_publications.source_run_id);
 get diagnostics changed=row_count;
 if changed>0 then
  for s in select old.current_source_run_id from public.analysis_parallel_reports old join public.historical_report_runs src on src.id=old.current_source_run_id
   where old.establishment_id=(p->>'establishment_id')::uuid and old.language=p->>'language' and old.state='completed'
   and (src.created_at,src.id)<(p_created_at,(p->>'current_source_run_id')::uuid)
   loop perform private.retention_retire_source(s.current_source_run_id,'SUPERSEDED_REPORT');end loop;
 end if;
 return changed>0;
end $function$

public.freeze_recent_review_source:
CREATE OR REPLACE FUNCTION public.freeze_recent_review_source(p_establishment uuid, p_organization uuid, p_language text, p_as_of timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare p public.review_corpus_policy;rows jsonb;overrides jsonb;meta jsonb;e jsonb;begin
 if current_user<>'service_role' then raise exception 'FORBIDDEN';end if;
 select * into p from public.review_corpus_policy where id for share;
 if p.paused or not p.enabled then raise exception 'RETENTION_TRANSITION_ACTIVE';end if;
 perform pg_advisory_xact_lock(hashtextextended('recent-text-corpus:'||p_establishment::text,0));
 perform private.apply_recent_review_retention(p_establishment,p_as_of);
 select jsonb_build_object('id',id,'organization_id',organization_id,'name',name,'rating',(select avg(rating) from public.reviews where establishment_id=p_establishment),'total_reviews',(select count(*) from public.reviews where establishment_id=p_establishment),'created_at',created_at) into e from public.establishments where id=p_establishment and organization_id=p_organization;
 if e is null then raise exception 'FORBIDDEN';end if;
 select jsonb_agg(jsonb_build_object('id',r.id,'rating',r.rating,'original_text',case when public.review_usable_text(r.original_text,r.text) is null then null else coalesce(nullif(r.original_text,''),r.text) end,'original_language',r.original_language,'text',case when public.review_usable_text(r.original_text,r.text) is null then null else r.text end,'published_at',r.published_at,
  'historical_import',r.historical_import,'has_negative_feedback',r.has_negative_feedback,'status',r.status,'review_detailed_rating',r.review_detailed_rating,'review_context',r.review_context,
  'ai_status',r.ai_status,'ai_suggested_reply',r.ai_suggested_reply,'ai_suggested_reply_language',r.ai_suggested_reply_language,'reply_draft_text',r.reply_draft_text,'reply_draft_language',r.reply_draft_language,
  'review_translations',coalesce((select jsonb_agg(jsonb_build_object('id',t.id,'language',t.language,'translated_text',t.translated_text,'source_text_sha256',t.source_text_sha256,'created_at',t.created_at,'updated_at',t.updated_at) order by t.language) from public.review_translations t where t.review_id=r.id),'[]'),
  'review_reply_drafts',coalesce((select jsonb_agg(jsonb_build_object('language',d.language,'ai_status',d.ai_status,'draft_text',d.draft_text,'ai_suggested_reply',d.ai_suggested_reply)) from public.review_reply_drafts d where d.review_id=r.id),'[]')) order by r.id),
  jsonb_build_object('epoch',p.epoch,'version',p.version,'as_of',p_as_of,'cutoff',null,'review_count',count(*),'period_start',min(r.published_at),'period_end',max(r.published_at),
   'review_ids',jsonb_agg(r.id order by r.id),'fingerprint',public.review_corpus_fingerprint(p_establishment)) into rows,meta
 from public.reviews r where r.establishment_id=p_establishment and r.id in(select public.retained_review_ids(p_establishment,p_as_of));
 if rows is null then raise exception 'NO_REVIEWS_AVAILABLE';end if; if not exists(select 1 from public.reviews where establishment_id=p_establishment and public.review_usable_text(original_text,text) is not null) then raise exception 'NO_TEXT_REVIEWS_AVAILABLE';end if;
 
 return jsonb_build_object('analysis_version',8,'analysis_text_policy','account_google_or_original_v1','retention',meta,'retention_frozen_rows',rows,'retention_establishment',e);
end $function$

public.commit_incremental_review_sync:
CREATE OR REPLACE FUNCTION public.commit_incremental_review_sync(p_job uuid, p_worker text, p_bundle jsonb, p_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare j public.review_sync_jobs;e public.establishments;target uuid;old_ids uuid[];after_ids uuid[];added integer;removed integer;known integer;ingested jsonb;answer jsonb;head_at timestamptz;head_id text;place jsonb;begin
 if current_user<>'service_role' then raise exception 'FORBIDDEN';end if;
 select establishment_id into target from public.review_sync_jobs where id=p_job;
 if target is null then return null;end if;
 perform pg_advisory_xact_lock(hashtextextended('recent-text-corpus:'||target::text,0));
 select * into e from public.establishments where id=target for update;
 select * into j from public.review_sync_jobs where id=p_job for update;
 if e.id is null or e.organization_id is distinct from j.organization_id then raise exception 'SYNC_INCREMENTAL_OBSOLETE';end if;
 if j.apify_run_id is distinct from p_result->>'run_id' or j.apify_dataset_id is distinct from p_result->>'dataset_id' then raise exception 'SYNC_INCREMENTAL_RUN_IDENTITY_CHANGED';end if;
 if j.status='completed' and j.incremental_result is not null then return j.incremental_result;end if;
 if j.status<>'running' or j.locked_by is distinct from left(p_worker,120) or j.lease_until<=clock_timestamp() then return null;end if;
 if j.incremental_receipt->>'status' is distinct from 'SUCCEEDED' or j.incremental_receipt->>'id' is distinct from j.apify_run_id then raise exception 'SYNC_INCREMENTAL_RUN_NOT_SUCCESSFUL';end if;
 if j.checkpoint_review_at is null or j.checkpoint_review_id is null then raise exception 'SYNC_INCREMENTAL_CHECKPOINT_MISSING';end if;
 if (j.checkpoint_review_id,j.checkpoint_review_at) is distinct from (e.last_review_id,e.last_review_at)
  or j.incremental_identity is not null and (j.incremental_identity->>'google_id',j.incremental_identity->>'place_id') is distinct from (e.google_id,e.place_id)
  or e.review_reload_barrier_at is not null and coalesce(j.provider_start_attempted_at,j.started_at,j.created_at)<e.review_reload_barrier_at then raise exception 'SYNC_INCREMENTAL_OBSOLETE';end if;
 if exists(select 1 from public.review_corpus_policy where paused or ingestions_paused or not enabled) then raise exception 'RETENTION_INGESTION_PAUSED';end if;
 if exists(select 1 from public.initial_import_jobs where establishment_id=e.id and status in('queued','running','retry')) then raise exception 'SYNC_INCREMENTAL_RELOAD_IN_PROGRESS';end if;
 if jsonb_typeof(p_bundle) is distinct from 'array' or jsonb_array_length(p_bundle)>150
  or (p_result->>'since')::timestamptz is distinct from j.checkpoint_review_at-interval '5 seconds'
  or coalesce((p_result->>'received')::integer,-1)<0 or coalesce((p_result->>'unique')::integer,-1)<0
  or (p_result->>'unique')::integer>(p_result->>'received')::integer
  or j.incremental_received is distinct from (p_result->>'received')::integer
  or jsonb_array_length(p_result->'external_ids') is distinct from (p_result->>'unique')::integer
  or exists(select 1 from jsonb_array_elements(p_bundle) x where (x#>>'{row,published_at}')::timestamptz<j.checkpoint_review_at-interval '5 seconds'
   or not (p_result->'external_ids' ? (x#>>'{row,external_review_id}'))) then raise exception 'SYNC_INCREMENTAL_RESULT_INVALID';end if;
 if j.incremental_version is not null and (j.incremental_version<>'google-reviews-incremental-v1' or j.incremental_input->>'reviewsStartDate' is distinct from p_result->>'since') then raise exception 'SYNC_INCREMENTAL_INPUT_MISMATCH';end if;
 if (p_result->>'received')::integer>=150 and (j.incremental_version is not null or coalesce((p_result->>'outside_window')::integer,0)=0) then raise exception 'SYNC_INCREMENTAL_LIMIT_REACHED';end if;
 select coalesce(array_agg(id),'{}') into old_ids from public.reviews where establishment_id=e.id;
 select count(*) into known from (select distinct btrim(value) external_id from jsonb_array_elements_text(p_result->'external_ids')) ids
 where exists(select 1 from public.reviews where establishment_id=e.id and external_review_id=ids.external_id)
  or exists(select 1 from private.review_seen_keys where establishment_id=e.id and external_key_sha256=encode(extensions.digest(ids.external_id,'sha256'),'hex'));
 select coalesce(jsonb_agg(value),'[]') into p_bundle from jsonb_array_elements(p_bundle) x(value)
 where not exists(select 1 from public.reviews where establishment_id=e.id and external_review_id=btrim(value#>>'{row,external_review_id}'))
  and not exists(select 1 from private.review_seen_keys where establishment_id=e.id and external_key_sha256=encode(extensions.digest(btrim(value#>>'{row,external_review_id}'),'sha256'),'hex'));
 if jsonb_array_length(p_bundle)>0 then
  -- All known IDs were removed under the same corpus lock used by ingestion/reload.
  -- The existing manual ingestion function therefore receives only genuinely new rows.
  ingested=public.ingest_recent_reviews(e.id,e.organization_id,p_bundle,'apify');
 end if;
 select coalesce(array_agg(id),'{}') into after_ids from public.reviews where establishment_id=e.id;
 select count(*) into added from unnest(after_ids) id where not(id=any(old_ids));
 select count(*) into removed from unnest(old_ids) id where not(id=any(after_ids));
 -- Use actual retained publication dates. An edited known review cannot move the watermark.
 select external_review_id,published_at into head_id,head_at from public.reviews
 where establishment_id=e.id and published_at>=j.checkpoint_review_at
 order by published_at desc,(external_review_id=j.checkpoint_review_id) desc,external_review_id collate "C",id limit 1;
 if head_at is null then raise exception 'SYNC_INCREMENTAL_HEAD_NOT_SAVED';end if;
 -- A zero-novelty run changes only verification/queue metadata: no retention, snapshot or report rewrite.
 if added>0 then
  place=p_result->'place';
  insert into public.establishment_snapshots(establishment_id,organization_id,captured_at,rating,total_reviews,provider,source_run_id,raw_place_payload)
  values(e.id,e.organization_id,clock_timestamp(),(place->>'rating')::numeric,(place->>'totalReviews')::integer,'apify','sync:'||j.id||':'||j.apify_run_id,coalesce(place->'rawPlacePayload','{}'))
  on conflict(establishment_id,provider,source_run_id) do nothing;
 end if;
 answer=jsonb_build_object('version','google-reviews-incremental-v1','received',(p_result->>'received')::integer,'unique',(p_result->>'unique')::integer,'already_known',known,'outside_window',(p_result->>'outside_window')::integer,'added',added,'removed',removed,'retained',cardinality(after_ids),'since',p_result->>'since','head_id',head_id,'head_at',head_at,'legacy_reused',coalesce((p_result->>'legacy_reused')::boolean,false),'empty',coalesce((p_result->>'empty')::boolean,false));
 update public.review_sync_jobs set head_review_id=head_id,head_review_at=head_at,reviews_fetched=greatest(reviews_fetched,(p_result->>'received')::integer),reviews_inserted=greatest(reviews_inserted,added),incremental_result=answer where id=j.id;
 if public.complete_review_sync_job(j.id,p_worker,clock_timestamp()) is distinct from true then raise exception 'SYNC_LEASE_LOST';end if;
 return answer;
end$function$

public.jev_batch_create_current:
CREATE OR REPLACE FUNCTION public.jev_batch_create_current(p_source uuid, p_manifest jsonb, p_sha text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
 SET jit TO 'off'
AS $function$
declare q public.report_generation_requests;s public.historical_report_runs;c public.analysis_parallel_launch_preparations;
 r uuid;v uuid;b jsonb;payload jsonb;expected_avis jsonb;expected_mapping jsonb;expected_questions jsonb;ids jsonb;actual_ids jsonb;rq jsonb;n int;
begin
 if current_user<>'service_role' or public.jls_restaurant_hash(p_manifest) is distinct from p_sha then raise exception 'FORBIDDEN';end if;
 select * into q from public.report_generation_requests where source_run_id=p_source for update;
 if q.id is null or q.engine<>'jev_sol_v2' or q.jev_transport<>'batch_initial_v1' then raise exception 'CURRENT_BATCH_REQUEST_REQUIRED';end if;
 if not public.report_request_evidence_selector_matches(q.evidence_selector_version,q.evidence_selector_sha256,p_manifest#>'{configuration,selector}')
 or q.evidence_selector_version<>'jls-direct4-negative-mixed-coverage-v1' and
  p_manifest#>'{template,evidence_selector}' is distinct from p_manifest#>'{configuration,selector}'
 or p_manifest#>'{template,evidence_selector}' is not null and
  p_manifest#>'{template,evidence_selector}' is distinct from p_manifest#>'{configuration,selector}'
 then raise exception 'CURRENT_BATCH_SELECTOR_CHANGED';end if;
 select id into r from public.analysis_jev_batch_runs where current_source_run_id=p_source;
 if r is not null then
  if not exists(select 1 from public.analysis_jev_batch_runs where id=r and manifest_sha256=p_sha and manifest=p_manifest) then raise exception 'CURRENT_BATCH_MANIFEST_CHANGED';end if;
  return r;
 end if;
 select * into s from public.historical_report_runs where id=p_source for update;
 select * into c from public.analysis_parallel_launch_preparations where current_source_run_id=s.id and sha256=p_manifest->>'source_protocol_sha256';
 if s.status not in('queued','running','retry') or s.created_at+interval '24 hours'<=now() or q.comparison_id is not null or c.id is null
 or not exists(select 1 from public.organization_members where organization_id=q.organization_id and user_id=q.authority_user_id and role in('owner','admin','manager')) then raise exception 'CURRENT_BATCH_CERTIFICATE_REQUIRED';end if;
 if not coalesce(p_manifest->>'version'='jev-current-batches-initial-v1' and p_manifest->>'transport'='batch_initial_v1'
 and p_manifest->>'organization_id'=q.organization_id::text and p_manifest->>'establishment_id'=q.establishment_id::text
 and p_manifest->>'authority_user_id'=q.authority_user_id::text and p_manifest->>'language'=q.language
 and p_manifest->'current_delivery'=c.body->'current_delivery' and p_manifest->'reference'=c.body->'reference'
 and p_manifest->'snapshot'=c.body->'source_snapshot' and p_manifest->>'snapshot_sha256'=c.body->>'source_snapshot_sha256'
 and p_manifest->'frozen_report'=c.body->'frozen_report'
 and p_manifest#>'{configuration,selector}'=c.body#>'{configuration,evidence_selector}'
 and p_manifest#>>'{configuration,sol_wire}'='jls-direct4-compact-sol-v1'
 and p_manifest#>>'{configuration,jev,version}'='jev-multi-review-initial-v1'
 and p_manifest#>>'{configuration,jev,model}'='jev-1.13.0'
 and p_manifest#>>'{configuration,jev,automatic_retry}'='false' and p_manifest#>>'{configuration,jev,max_attempts_per_batch}'='1'
 and p_manifest#>>'{configuration,jev,target_reviews}'='50' and p_manifest#>'{configuration,jev,confidence_threshold}'='null'::jsonb
 and p_manifest#>>'{configuration,jev,common_instructions_sha256}'='3a82a9c032217a0d10ba8a9ceccdafb71bc702366145d5837a324af580c20d22'
 and p_manifest->>'automatic_retry'='false' and p_manifest->>'max_sol_calls'='1' and p_manifest->>'max_luna_calls'='0' and p_manifest->>'max_apify_calls'='0'
 and jsonb_typeof(p_manifest->'plans')='array' and jsonb_array_length(p_manifest->'plans')>0
 and (p_manifest->>'max_new_jev_calls')::int=jsonb_array_length(p_manifest->'plans'),false) then raise exception 'CURRENT_BATCH_CONFIGURATION_CHANGED';end if;
 rq=(p_manifest#>>'{template,request_json}')::jsonb;
 if not coalesce(rq->>'model'='gpt-6.1-sol' and rq#>>'{reasoning,effort}'='low' and rq->>'max_output_tokens'='9500'
 and rq#>>'{text,format,name}'='jls_direct4_compact_sol_v1' and rq#>>'{text,format,strict}'='true'
 and public.jls_restaurant_hash(rq#>'{text,format,schema}')='a479cb3b10c97557ee750e9484118629bfe8f6580edc945e31d6d864793d194c'
 and encode(extensions.digest(rq#>>'{input,0,content}','sha256'),'hex')=case q.language when 'fr' then '2b27ff48b9d0de25e92af4e640fb60dd75b9eccbe0b4ecc109b2955c531aae37' else '8aac8e2a06d412ca0425a00b919c03a89490a94c13e4462e6f9119dd60569c86' end
 and p_manifest#>>'{template,packet,language}'=q.language,false) then raise exception 'CURRENT_BATCH_SOL_TEMPLATE_CHANGED';end if;
 if rq is distinct from jsonb_build_object('model','gpt-6.1-sol','reasoning',jsonb_build_object('effort','low'),'max_output_tokens',9500,
  'input',jsonb_build_array(jsonb_build_object('role','system','content',rq#>>'{input,0,content}'),jsonb_build_object('role','user','content','{}')),
  'text',jsonb_build_object('format',jsonb_build_object('type','json_schema','name','jls_direct4_compact_sol_v1','strict',true,'schema',rq#>'{text,format,schema}')))
  then raise exception 'CURRENT_BATCH_SOL_PARAMETERS_CHANGED';end if;
 select jsonb_agg(x->>'id' order by x->>'id') into ids from jsonb_array_elements(c.body#>'{source_snapshot,reviews}') x where nullif(x->>'analysis_text','') is not null;
 select jsonb_object_agg(g::text,(select count(*) from jsonb_array_elements(c.body#>'{source_snapshot,reviews}') x where (x->>'rating')::int=g)) into expected_mapping from generate_series(1,5) g;
 select jsonb_object_agg(g::text,(select count(*) from jsonb_array_elements(c.body#>'{source_snapshot,reviews}') x where (x->>'rating')::int=g and nullif(x->>'analysis_text','') is not null)) into expected_questions from generate_series(1,5) g;
 expected_avis=jsonb_build_object('scope',jsonb_build_object('source_reviews',jsonb_array_length(c.body#>'{source_snapshot,reviews}'),'analysed_text_reviews',jsonb_array_length(ids),'textless_statistics_only',jsonb_array_length(c.body#>'{source_snapshot,reviews}')-jsonb_array_length(ids)),
  'counts','{}'::jsonb,'star_distribution_all',expected_mapping,'star_distribution_analysed',expected_questions,'categories',p_manifest#>'{template,statistics,categories}','uncertainty_preserved',true,'frequency_unit','distinct_review_per_category_not_specific_incident');
 if p_manifest#>'{template,statistics}' is distinct from expected_avis or public.jls_restaurant_hash(p_manifest#>'{template,statistics,categories}') is distinct from '970e557234f509df3254c2c84f5a298e704cd5c241acb1b850b2cbb56da841e0' then raise exception 'CURRENT_BATCH_STATISTICS_TEMPLATE_CHANGED';end if;
 select jsonb_agg(i.id order by i.id) into actual_ids from jsonb_array_elements(p_manifest->'plans') p cross join lateral jsonb_array_elements_text(p->'review_ids') i(id);
 if ids is distinct from actual_ids then raise exception 'CURRENT_BATCH_REVIEW_SET_CHANGED';end if;
 n=0;
 for b in select value from jsonb_array_elements(p_manifest->'plans') loop
  n=n+1;payload=(b->>'request_wire')::jsonb;
  if not coalesce((b->>'number')::int=n and (b->>'reviews')::int between 1 and 50
   and jsonb_array_length(b->'review_ids')=(b->>'reviews')::int
   and b#>>'{preflight,passed}'='true' and b#>>'{preflight,truncated_reviews}'='0'
   and (b#>>'{preflight,guarded_total_tokens}')::int<=64000 and (b#>>'{preflight,guarded_largest_pair_tokens}')::int<=32000
   and octet_length(b->>'request_wire')<=33554432 and b->>'request_sha256'=encode(extensions.digest(b->>'request_wire','sha256'),'hex')
   and public.jls_restaurant_hash(payload#>'{state,consignes_communes}')='3a82a9c032217a0d10ba8a9ceccdafb71bc702366145d5837a324af580c20d22',false) then raise exception 'CURRENT_BATCH_REQUEST_GUARD_CHANGED';end if;
  select jsonb_object_agg('review_'||i.id,x->>'analysis_text') into expected_avis from jsonb_array_elements_text(b->'review_ids') i(id)
   join jsonb_array_elements(c.body#>'{source_snapshot,reviews}') x on x->>'id'=i.id;
  select jsonb_object_agg('r'||lpad(i.ord::text,3,'0')||'_'||cat,jsonb_build_object('review_id',i.id,'category',cat)),
   jsonb_object_agg('r'||lpad(i.ord::text,3,'0')||'_'||cat,jsonb_build_object('type','choice','instructions','Classe '||cat||' pour le seul avis review_'||i.id||' selon consignes_communes.',
    'criteria','{"positive":null,"negative":null,"mixed":null,"neutral":null,"uncertain":null,"not_mentioned":null}'::jsonb))
  into expected_mapping,expected_questions from jsonb_array_elements_text(b->'review_ids') with ordinality i(id,ord) cross join unnest(array['service','price','quality','ambiance']) cat;
  if b->'mapping' is distinct from expected_mapping or payload is distinct from jsonb_build_object('model','jev-1.13.0','state',jsonb_build_object('avis',expected_avis,'consignes_communes',payload#>'{state,consignes_communes}'),'questions',expected_questions)
   then raise exception 'CURRENT_BATCH_MAPPING_OR_TEXT_CHANGED';end if;
 end loop;
 v=gen_random_uuid();
 insert into public.analysis_parallel_reports(id,organization_id,establishment_id,reference_generation_id,current_source_run_id,language,configuration_version,corpus_sha256,source_report,source_reviews,state,statistics)
 values(v,q.organization_id,q.establishment_id,s.generation_id,s.id,q.language,'jev-multi-review-initial-v1',c.body#>>'{source_snapshot,source_reviews_sha256}',p_manifest->'frozen_report',p_manifest#>'{snapshot,reviews}','generating',jsonb_build_object('scope',jsonb_set(p_manifest#>'{template,statistics,scope}','{analysed_text_reviews}','0')));
 insert into public.analysis_jev_batch_runs(organization_id,establishment_id,current_source_run_id,report_id,snapshot,snapshot_sha256,template,manifest,manifest_sha256,source_manifest_sha256,authorization_evidence,expires_at,max_new_jev_calls,armed)
 values(q.organization_id,q.establishment_id,s.id,v,p_manifest->'snapshot',p_manifest->>'snapshot_sha256',p_manifest->'template',p_manifest,p_sha,p_sha,'Current report request '||q.id::text||'; one native attempt per frozen batch; no automatic retry.',s.created_at+interval '24 hours',n,true) returning id into r;
 insert into public.analysis_jev_batch_tasks(run_id,organization_id,number,reviews,request_wire,request_sha256,mapping,preflight)
 select r,q.organization_id,(pb.value->>'number')::int,(pb.value->>'reviews')::int,pb.value->>'request_wire',pb.value->>'request_sha256',pb.value->'mapping',pb.value->'preflight' from jsonb_array_elements(p_manifest->'plans') pb(value);
 update public.report_generation_requests set comparison_id=v where id=q.id;
 update public.historical_report_runs set status='running',locked_by=null,lease_until=null,total_steps=n+1,updated_at=now() where id=s.id;
 perform public.jev_batch_wake(r);return r;
end $function$

public.jev_batch_claim_sol:
CREATE OR REPLACE FUNCTION public.jev_batch_claim_sol(p_run uuid, p_worker text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r public.analysis_jev_batch_runs;begin if not public.retention_batch_allowed(p_run) then return false;end if;
 if current_user<>'service_role' then raise exception 'FORBIDDEN';end if;
 select * into r from public.analysis_jev_batch_runs where id=p_run for update;
 if not r.armed or r.status<>'running' or r.expires_at<=now() or r.stage<>'sol' then return false;end if;
 if r.sol_request_count=1 then
  if r.sol_receipt is null and r.sol_lease_until<now() then
   update public.analysis_jev_batch_runs set status='billing_uncertain',error_code='SOL_OUTCOME_UNKNOWN_NO_RETRY',armed=false where id=r.id;
   update public.analysis_parallel_reports set state='billing_uncertain',error_code='SOL_OUTCOME_UNKNOWN_NO_RETRY' where id=r.report_id;
  end if;return false;
 end if;
 if r.envelope is null or exists(select 1 from public.analysis_jev_batch_tasks where run_id=r.id and status<>'completed') then raise exception 'BATCH_SOL_NOT_READY';end if;
 update public.analysis_jev_batch_runs set sol_request_count=1,sol_worker=p_worker,sol_lease_until=now()+interval '150 seconds' where id=r.id;return true;
end $function$

public.jev_batch_save_projection:
CREATE OR REPLACE FUNCTION public.jev_batch_save_projection(p_task uuid, p_worker text, p_body jsonb, p_sha text, p_error text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare t public.analysis_jev_batch_tasks;r public.analysis_jev_batch_runs;done int;begin
 if current_user<>'service_role' or public.jls_restaurant_hash(p_body)<>p_sha then raise exception 'FORBIDDEN';end if;
 select * into t from public.analysis_jev_batch_tasks where id=p_task for update;
 if t.status='completed' then return t.projection_sha256=p_sha;end if;
 if t.status<>'received' or t.worker is distinct from p_worker then return false;end if;
 select * into r from public.analysis_jev_batch_runs where id=t.run_id for update;
 update public.analysis_jev_batch_tasks set projection=p_body,projection_sha256=p_sha,status=case when p_error is null then 'completed' else 'invalid_output' end,error_code=p_error,completed_at=now(),lease_until=null where id=t.id;
 select coalesce(sum(reviews),0) into done from public.analysis_jev_batch_tasks where run_id=r.id and status='completed';
 update public.analysis_parallel_reports set statistics=jsonb_set(statistics,'{scope,analysed_text_reviews}',to_jsonb(done)) where id=r.report_id;
 if not exists(select 1 from public.analysis_jev_batch_tasks where run_id=r.id and status<>'completed') then update public.analysis_jev_batch_runs set stage='prepare_evidence' where id=r.id;end if;
 perform public.jev_batch_wake(r.id);return true;
end $function$

public.jev_batch_recover:
CREATE OR REPLACE FUNCTION public.jev_batch_recover()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r public.analysis_jev_batch_runs;n int=0;begin
 if current_user<>'service_role' and current_user<>'postgres' then raise exception 'FORBIDDEN';end if;
 for r in select * from public.analysis_jev_batch_runs where current_source_run_id is not null and armed and status='running' loop
  if r.expires_at<=now() then
   update public.analysis_jev_batch_tasks set status='unknown',error_code='BATCH_OUTCOME_UNKNOWN_NO_RETRY' where run_id=r.id and status='reserved' and receipt is null;
   update public.analysis_jev_batch_runs set status='authorization_expired',armed=false,error_code='BATCH_AUTHORIZATION_EXPIRED' where id=r.id;
   update public.analysis_parallel_reports set state='authorization_expired',error_code='BATCH_AUTHORIZATION_EXPIRED' where id=r.report_id;
  else perform public.jev_batch_wake(r.id);n=n+1;
  end if;
 end loop;return n;
end $function$

public.retention_batch_allowed:
CREATE OR REPLACE FUNCTION public.retention_batch_allowed(p_run uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.review_corpus_policy;b public.analysis_jev_batch_runs;sc public.report_corpus_scopes;begin
 select * into p from public.review_corpus_policy where id for share;
 if p.paused then return false;end if;
 if not p.enabled then return true;end if;
 select * into b from public.analysis_jev_batch_runs where id=p_run;
 if b.id is null or b.current_source_run_id is null then return false;end if;
 perform pg_advisory_xact_lock(hashtextextended('recent-text-corpus:'||b.establishment_id::text,0));
 select * into sc from public.report_corpus_scopes where source_run_id=b.current_source_run_id;
 if sc.source_run_id is null or sc.policy_epoch<>p.epoch or sc.stale or sc.fingerprint<>public.review_corpus_fingerprint(b.establishment_id) then
  update public.analysis_jev_batch_runs set armed=false,status='blocked',error_code='CORPUS_CHANGED_DURING_GENERATION' where id=b.id;
  return false;
 end if;
 if exists(select 1 from public.analysis_jev_batch_tasks t join private.provider_attempt_ledger l on l.request_sha256=t.request_sha256 and l.outcome='unknown' and l.provider='jev' where t.run_id=b.id and t.status='pending' and t.request_count=0) then
  update public.analysis_jev_batch_runs set armed=false,status='blocked',error_code='PREVIOUS_IDENTICAL_REQUEST_OUTCOME_UNKNOWN' where id=b.id;return false;
 end if;
 return true;
end $function$

public.jev_batch_claim:
CREATE OR REPLACE FUNCTION public.jev_batch_claim(p_run uuid, p_worker text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r public.analysis_jev_batch_runs;t public.analysis_jev_batch_tasks;begin if not public.retention_batch_allowed(p_run) then return null;end if;
 if current_user<>'service_role' then raise exception 'FORBIDDEN';end if;
 -- Serializes only the short reservation transaction, never the HTTP request.
 perform pg_advisory_xact_lock(hashtextextended('jev-native-batch-account-slot-v1',0));
 select * into r from public.analysis_jev_batch_runs where id=p_run for update;
 if r.id is null or not r.armed or r.status<>'running' or r.expires_at<=now() then return null;end if;
 update public.analysis_jev_batch_tasks set status='unknown',error_code='BATCH_OUTCOME_UNKNOWN_NO_RETRY' where run_id=p_run and status='reserved' and lease_until<now();
 select * into t from public.analysis_jev_batch_tasks where run_id=p_run and (status='pending' and request_count=0 or status='received' and (lease_until is null or lease_until<now())) order by number for update skip locked limit 1;
 if t.id is null then
  if exists(select 1 from public.analysis_jev_batch_tasks where run_id=p_run and status in('unknown','invalid_output')) then
   perform public.jev_batch_refresh_usage(r.id);
   update public.analysis_jev_batch_runs set status='blocked',error_code='BATCH_INCOMPLETE_NO_SOL',armed=false where id=p_run;
   update public.analysis_parallel_reports set state='blocked',error_code='BATCH_INCOMPLETE_NO_SOL' where id=r.report_id;
  end if;return null;
 end if;
 if t.status='pending' then
  if exists(select 1 from public.analysis_jev_batch_tasks where status='reserved' and lease_until>now()) then return null;end if;
  if (select count(*) from public.analysis_jev_batch_tasks where run_id=p_run and request_count=1)>=r.max_new_jev_calls then raise exception 'BATCH_NEW_JEV_NOT_AUTHORIZED';end if;
  update public.analysis_jev_batch_tasks set status='reserved',request_count=1,reserved_at=now(),lease_until=now()+interval '150 seconds',worker=p_worker where id=t.id returning * into t;
  perform public.jev_batch_refresh_usage(r.id);
 else update public.analysis_jev_batch_tasks set worker=p_worker,lease_until=now()+interval '150 seconds' where id=t.id returning * into t;
 end if;return to_jsonb(t);
end $function$

public.jev_batch_receive:
CREATE OR REPLACE FUNCTION public.jev_batch_receive(p_task uuid, p_worker text, p_receipt jsonb, p_sha text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
 SET jit TO 'off'
AS $function$
declare t public.analysis_jev_batch_tasks;begin
 if current_user<>'service_role' or public.jls_restaurant_hash(p_receipt) is distinct from p_sha then raise exception 'FORBIDDEN';end if;
 select * into t from public.analysis_jev_batch_tasks where id=p_task for update;
 if t.receipt is not null then return t.receipt_sha256=p_sha;end if;
 if t.status not in('reserved','unknown') or t.worker is distinct from p_worker or t.request_count<>1 or p_receipt->>'request_sha256' is distinct from t.request_sha256 then return false;end if;
 update public.analysis_jev_batch_tasks set receipt=p_receipt,receipt_sha256=p_sha,
  status=case when p_receipt->>'raw_response_text' is null then 'unknown' else 'received' end,
  error_code=case when p_receipt->>'raw_response_text' is null then 'BATCH_OUTCOME_UNKNOWN_NO_RETRY' else null end,lease_until=null,
  input_tokens=case when p_receipt#>>'{usage,input_tokens}' ~ '^[0-9]+$' then (p_receipt#>>'{usage,input_tokens}')::bigint else null end,
  output_tokens=case when p_receipt#>>'{usage,output_tokens}' ~ '^[0-9]+$' then (p_receipt#>>'{usage,output_tokens}')::bigint else null end,
  duration_ms=case when jsonb_typeof(p_receipt->'duration_ms')='number' then (p_receipt->>'duration_ms')::double precision else null end,
  served_model=p_receipt->>'served_model',provider_request_id=p_receipt->>'provider_request_id' where id=t.id;
 return true;
end $function$

public.jev_batch_continue_received:
CREATE OR REPLACE FUNCTION public.jev_batch_continue_received(p_task uuid, p_sha text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
 SET jit TO 'off'
AS $function$
declare t public.analysis_jev_batch_tasks;other uuid;begin
 if current_user<>'service_role' then raise exception 'FORBIDDEN';end if;
 select * into t from public.analysis_jev_batch_tasks where id=p_task;
 if t.receipt is null or t.receipt_sha256 is distinct from p_sha then return false;end if;
 perform public.jev_batch_refresh_usage(t.run_id);
 perform public.jev_batch_wake(t.run_id);
 select id into other from public.analysis_jev_batch_runs br where current_source_run_id is not null and id<>t.run_id and armed and status='running' and expires_at>now()
  and exists(select 1 from public.analysis_jev_batch_tasks bt where bt.run_id=br.id and bt.status='pending' and bt.request_count=0) order by created_at limit 1;
 if other is not null then perform public.jev_batch_wake(other);end if;return true;
end $function$
